#include <WiFi.h>

// До 10 точек доступа — железный лимит ESP32
const char* NAMES[] = {
  "Free WiFi",
  "Это не вирус",
  "Нажми для приза",
  "WiFi_от_соседа",
  "Секретная_сеть",
  "Скачивай_диплом",
  "Тут_нет_интернета",
  "Подключись_и_плачь",
  "Роутер_в_духовке",
  "Ещё_одна_точка"
};

const int COUNT = sizeof(NAMES) / sizeof(NAMES[0]);

void setup() {
  WiFi.mode(WIFI_AP);
  for (int i = 0; i < COUNT; i++) {
    bool ok = WiFi.softAP(NAMES[i], "", i + 1);  // каналы 1..10
    Serial.printf("%s: %s\n", NAMES[i], ok ? "запущена" : "ошибка");
  }
}

void loop() {
}
